package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.HardwareMap;
import com.qualcomm.robotcore.hardware.Servo;
import com.qualcomm.robotcore.util.Range;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;

// Generated by refract-suite ftc-construct. One yaw servo per turret (team 2026-10-17), each aimed on its own.
// Modelled as a position servo (the part is not chosen yet): servo position = forward + perDeg x angle, from
// program 3. The servo reports nothing back, so where the turret is comes from the last command and the turn
// speed program 3 timed: a turret counts as there once the move has had time to finish. Side 0 = front, 1 = back;
// angles in that turret's own degrees, 0 = straight forward, + = left. Never commanded in INIT (R102): a servo
// with no signal stays where the turret was put, and the first command (at START) moves it; until a move from the far
// end of its travel would have finished, it does not count as there.
public class Yaw {
    public static final int FRONT = 0, BACK = 1;
    // a command change smaller than this does not move the servo (well under a servo's deadband)
    private static final double SAME_DEG = 0.05;

    private final Servo[] servos = new Servo[2];
    private final double[] commandDeg = {Double.NaN, Double.NaN}, estDeg = {Double.NaN, Double.NaN};
    private long lastNanos = 0;

    public Yaw(HardwareMap hardwareMap) {
        servos[FRONT] = hardwareMap.get(Servo.class, DeviceNames.FRONT_YAW);
        servos[BACK] = hardwareMap.get(Servo.class, DeviceNames.BACK_YAW);
    }

    public static double forward(int side) {
        return side == FRONT ? Tuned.frontYawForward : Tuned.backYawForward;
    }

    public static double perDeg(int side) {
        return side == FRONT ? Tuned.frontYawPerDeg : Tuned.backYawPerDeg;
    }

    public static double minDeg(int side) {
        return side == FRONT ? Tuned.frontYawMinDeg : Tuned.backYawMinDeg;
    }

    public static double maxDeg(int side) {
        return side == FRONT ? Tuned.frontYawMaxDeg : Tuned.backYawMaxDeg;
    }

    public static boolean calibrated(int side) {
        return Tuned.isSet(forward(side), perDeg(side), minDeg(side), maxDeg(side)) && perDeg(side) != 0;
    }

    public static boolean calibrated() {
        return calibrated(FRONT) && calibrated(BACK) && Tuned.isSet(Tuned.yawDegPerS) && Tuned.yawDegPerS > 0;
    }

    public static boolean inLimits(int side, double deg) {
        return deg >= minDeg(side) && deg <= maxDeg(side);
    }

    public static double position(int side, double deg) {
        return forward(side) + perDeg(side) * deg;
    }

    // Turn a turret to deg (clipped to its limits). Call every loop for both turrets, then update().
    public void aim(int side, double deg) {
        if (!calibrated() || Double.isNaN(deg)) return;
        double target = Range.clip(deg, minDeg(side), maxDeg(side));
        if (!Double.isNaN(commandDeg[side]) && Math.abs(target - commandDeg[side]) < SAME_DEG) return;
        // the first move: the turret should have been placed straight forward, but nothing reads where it is, so count it
        // as on target only once a move from the far end of its travel would have finished (under a second, once)
        if (Double.isNaN(estDeg[side])) estDeg[side] = Math.abs(target - minDeg(side)) > Math.abs(target - maxDeg(side)) ? minDeg(side) : maxDeg(side);
        commandDeg[side] = target;
        servos[side].setPosition(Range.clip(position(side, target), 0, 1));
    }

    // Moves each turret's estimate toward its command at the timed turn speed. Every loop, after aim().
    public void update() {
        long now = System.nanoTime();
        double dt = lastNanos == 0 ? 0 : Math.min(0.1, (now - lastNanos) / 1e9);
        lastNanos = now;
        if (!calibrated()) return;
        for (int side = 0; side < 2; side++) {
            if (Double.isNaN(commandDeg[side])) continue;
            double gap = commandDeg[side] - estDeg[side], step = Tuned.yawDegPerS * dt;
            estDeg[side] = Math.abs(gap) <= step ? commandDeg[side] : estDeg[side] + Math.signum(gap) * step;
        }
    }

    // where the turret is (estimate); NaN before its first command
    public double deg(int side) {
        return estDeg[side];
    }

    public double commandDeg(int side) {
        return commandDeg[side];
    }

    // the last command has had time to finish
    public boolean arrived(int side) {
        return !Double.isNaN(commandDeg[side]) && estDeg[side] == commandDeg[side];
    }
}
